-- LaundryFlow: SQL queries used by the application
-- Generated by `npm run queries:export` from src/lib/queries.js. Do not edit by hand:
-- change the query in the app, then export again.
-- $1, $2... are parameters supplied by the application.

-- R01: Find bags by number
-- The counter staff type 1054 and pick B 1054 or G 1054 from the list. The prefix is part of the bag tag, so one number can match two students.
-- Parameters: $1 = bag_number
SELECT student_id, bag_prefix, bag_number, full_name
FROM students
WHERE bag_number = $1
  AND is_active
ORDER BY bag_prefix;

-- R02: Counter queue: orders waiting to be received
-- Everything a student has submitted that no staff member has counted yet, oldest first.
-- Parameters: none
SELECT o.order_id, o.submitted_at, o.declared_count,
       s.bag_prefix, s.bag_number, s.full_name
FROM orders o
JOIN students s ON s.student_id = o.student_id
WHERE o.order_status = 'SUBMITTED'
ORDER BY o.submitted_at;

-- R03: A student's orders with fines
-- History page for one student. The fine is optional, so it is a LEFT JOIN: an order within the free limit has no row in fines.
-- Parameters: $1 = student_id
SELECT o.order_id, o.order_status, o.declared_count, o.verified_count,
       o.submitted_at, o.received_at, o.ready_at, o.collected_at,
       f.fine_amount, f.fine_status
FROM orders o
LEFT JOIN fines f ON f.order_id = o.order_id
WHERE o.student_id = $1
ORDER BY o.submitted_at DESC;

-- R04: Find a student by email
-- Used after Google sign-in to link the login to a student profile. Emails are stored in lowercase and are unique.
-- Parameters: $1 = email
SELECT student_id, enrollment_no, full_name, email, bag_prefix, bag_number,
       bag_verified_at, is_active
FROM students
WHERE email = $1;

-- R05: Find an active staff member by email
-- Used after Google sign-in to see whether the account belongs to laundry staff. Staff are added by an admin, so being on this list is what grants staff access.
-- Parameters: $1 = email
SELECT staff_id, full_name, email, role
FROM staff
WHERE email = $1
  AND is_active;

-- W01: Submit an order
-- A student declares how many clothes they are handing in. Staff count them later (verified_count stays NULL until then).
-- Parameters: $1 = student_id, $2 = declared_count
INSERT INTO orders (student_id, order_status, declared_count, submitted_at)
VALUES ($1, 'SUBMITTED', $2, now())
RETURNING order_id, submitted_at;

-- W02: Register a student profile
-- A student creates their own profile after their first Google sign-in. The bag tag is unverified until staff check it at the first drop-off (bag_verified_at and bag_verified_by stay NULL).
-- Parameters: $1 = enrollment_no, $2 = full_name, $3 = email, $4 = bag_prefix, $5 = bag_number
INSERT INTO students (enrollment_no, full_name, email, bag_prefix, bag_number)
VALUES ($1, $2, $3, $4, $5)
RETURNING student_id;

-- R10: Check student's active laundry order
-- Checks whether a student has an order that is submitted, received, or ready.
-- Parameters: $1 = student_id
SELECT order_id, order_status
FROM orders
WHERE student_id = $1
  AND order_status IN ('SUBMITTED', 'RECEIVED', 'READY')
LIMIT 1;

-- W10: Submit order if no active order exists
-- Atomically checks for an active order and inserts a new order if none exists.
-- Parameters: $1 = student_id, $2 = declared_count
INSERT INTO orders (student_id, order_status, declared_count, submitted_at)
SELECT $1, 'SUBMITTED', $2, now()
WHERE NOT EXISTS (
  SELECT 1
  FROM orders
  WHERE student_id = $1
    AND order_status IN ('SUBMITTED', 'RECEIVED', 'READY')
)
ON CONFLICT DO NOTHING
RETURNING order_id, submitted_at;

-- R20: Current fine policy
-- Counter receipt: returns the latest fine policy effective on the receipt date. The date is taken in India time, because the database server runs in UTC.
-- Parameters: none
SELECT policy_id, free_limit, fine_per_extra
FROM policies
WHERE effective_from <= (now() AT TIME ZONE 'Asia/Kolkata')::date
ORDER BY effective_from DESC
LIMIT 1;

-- W20: Receive a submitted order
-- Records the verified count, policy, receipt time, and staff member. Only a still-submitted order can be received.
-- Parameters: $1 = order_id, $2 = verified_count, $3 = staff_id, $4 = policy_id
UPDATE orders
SET order_status = 'RECEIVED',
    verified_count = $2,
    received_at = now(),
    received_by = $3,
    policy_id = $4
WHERE order_id = $1
  AND order_status = 'SUBMITTED'
RETURNING order_id;

-- W21: Create an unpaid fine
-- Stores a positive fine calculated from the verified count and effective policy. Called inside the receipt transaction only when the amount is greater than zero.
-- Parameters: $1 = order_id, $2 = fine_amount
INSERT INTO fines (order_id, fine_amount, fine_status)
VALUES ($1, $2, 'UNPAID')
RETURNING order_id;

-- W22: Verify a bag tag
-- Records the first in-person verification time and the authenticated staff member. Does not overwrite an existing verification.
-- Parameters: $1 = student_id, $2 = staff_id
UPDATE students
SET bag_verified_at = now(),
    bag_verified_by = $2
WHERE student_id = $1
  AND is_active
  AND bag_verified_at IS NULL
RETURNING student_id, bag_verified_at;

-- R30: Unpaid fines
-- Every fine not yet paid or waived, oldest first, with the student's bag tag. Uses the partial index ix_fines_unpaid.
-- Parameters: none
SELECT f.order_id, f.fine_amount, o.received_at,
       s.bag_prefix, s.bag_number, s.full_name
FROM fines f
JOIN orders o ON o.order_id = f.order_id
JOIN students s ON s.student_id = o.student_id
WHERE f.fine_status = 'UNPAID'
ORDER BY o.received_at;

-- R31: Orders ready to wash
-- Lists all received orders waiting to be washed, with the student's bag tag, verified clothes count and received time.
-- Parameters: none
SELECT o.order_id, o.verified_count, o.received_at,
       s.bag_prefix, s.bag_number, s.full_name
FROM orders o
JOIN students s ON s.student_id = o.student_id
WHERE o.order_status = 'RECEIVED'
ORDER BY o.received_at;

-- R32: Orders waiting for pickup
-- Lists all ready orders waiting to be collected by students, with their bag tag and ready time.
-- Parameters: none
SELECT o.order_id, o.verified_count, o.ready_at,
       s.bag_prefix, s.bag_number, s.full_name
FROM orders o
JOIN students s ON s.student_id = o.student_id
WHERE o.order_status = 'READY'
ORDER BY o.ready_at;

-- W30: Mark order ready
-- Changes a received order to READY and records when washing is completed. Only received orders can be updated.
-- Parameters: $1 = order_id
UPDATE orders
SET order_status = 'READY',
    ready_at = now()
WHERE order_id = $1
  AND order_status = 'RECEIVED'
RETURNING order_id;

-- W31: Mark order collected
-- Marks a ready order as COLLECTED and records the collection time and staff member responsible.
-- Parameters: $1 = order_id, $2 = staff_id
UPDATE orders
SET order_status = 'COLLECTED',
    collected_at = now(),
    collected_by = $2
WHERE order_id = $1
  AND order_status = 'READY'
RETURNING order_id;

-- W32: Mark fine paid
-- Marks an unpaid fine as PAID and records the payment time. Already paid or waived fines cannot be updated.
-- Parameters: $1 = order_id
UPDATE fines
SET fine_status = 'PAID',
    fine_paid_at = now()
WHERE order_id = $1
  AND fine_status = 'UNPAID'
RETURNING order_id;

-- W33: Waive unpaid fine
-- Waives an unpaid fine and records the responsible staff member and reason for the waiver.
-- Parameters: $1 = order_id, $2 = staff_id, $3 = waiver_reason
UPDATE fines
SET fine_status = 'WAIVED',
    waived_by = $2,
    waiver_reason = $3
WHERE order_id = $1
  AND fine_status = 'UNPAID'
RETURNING order_id;

-- R40: All staff
-- Admin page: everyone on the staff list, active first.
-- Parameters: none
SELECT staff_id, full_name, email, role, is_active
FROM staff
ORDER BY is_active DESC, full_name;

-- R41: Fine policy history
-- Admin page: every fine rule, newest first. Rules are never edited; a change is a new row, so each order keeps the rule it was counted under (orders.policy_id).
-- Parameters: none
SELECT policy_id, effective_from, free_limit, fine_per_extra
FROM policies
ORDER BY effective_from DESC;
